export const MIN_AREA_RESIDENTS = 10;

export interface KecamatanMetric {
  kecamatan: string;
  residents: number;
  avg_travel_min: number;
  avg_cost_idr: number;
  stuck_count: number;
}

/**
 * Roll up kelurahan metrics to kecamatan level, weighted by residents
 * (matching services/orchestrator/app/compare.py `kecamatan_metrics`).
 */
export function rollupByKecamatan(
  rows: Array<{
    kelurahan: string;
    residents?: number;
    avg_travel_min: number;
    avg_cost_idr: number;
    stuck_count: number;
  }>
): KecamatanMetric[] {
  const totals: Record<
    string,
    { residents: number; travel: number; cost: number; stuck_count: number }
  > = {};

  for (const row of rows) {
    const kec = KELURAHAN_TO_KECAMATAN[row.kelurahan];
    const residents = typeof row.residents === "number" && row.residents > 0 ? row.residents : 1;
    if (!kec || residents <= 0) continue;
    if (!totals[kec]) {
      totals[kec] = { residents: 0, travel: 0, cost: 0, stuck_count: 0 };
    }
    const t = totals[kec];
    t.residents += residents;
    t.travel += row.avg_travel_min * residents;
    t.cost += (row.avg_cost_idr || 0) * residents;
    t.stuck_count += row.stuck_count || 0;
  }

  return Object.keys(totals)
    .sort()
    .map((kec) => {
      const t = totals[kec];
      return {
        kecamatan: kec,
        residents: t.residents,
        avg_travel_min: Math.round((t.travel / t.residents) * 10) / 10,
        avg_cost_idr: Math.round(t.cost / t.residents),
        stuck_count: t.stuck_count,
      };
    });
}

